  'وقتی نسخه کش‌شده منقضی شده یا سرور اصلی خطا می‌دهد چه اتفاقی بیفتد.': 'What happens when the cached copy has expired or the origin returns an error.',
  'وقتی مدت کش فایلی تمام شده، بازدیدکننده بی‌درنگ همان نسخه قبلی را می‌گیرد و CDN نسخه تازه را در پس‌زمینه از سرور اصلی دریافت می‌کند؛ هیچ بازدیدکننده‌ای منتظر سرور اصلی نمی‌ماند. پیشنهادی: روشن.': 'When a file\'s cache time is over, visitors immediately get the previous copy while the CDN fetches a fresh one from the origin in the background; no visitor waits for the origin. Recommended: on.',
  'نمایش نسخه قدیمی هنگام خطای سرور اصلی': 'Serve stale content on origin errors',
  'اگر سرور اصلی خطای ۵xx بدهد یا پاسخ ندهد، تا این مدت پس از انقضا نسخه کش‌شده نمایش داده می‌شود تا سایت از دسترس خارج نشود.': 'If the origin returns a 5xx error or does not respond, the cached copy is served for this long after expiry so the site stays up.',
  'اگر سرور اصلی در هدر': 'If the origin sends',
  'یا': 'or',
  'بفرستد، همان هم رعایت می‌شود.': 'in the header, that is honoured too.',
  'یک لایه کش میانی جلوی سرور اصلی شما.': 'An intermediate cache layer in front of your origin server.',
  'Origin Shield (کش لایه‌ای)': 'Origin Shield (tiered cache)',
  'نودهای CDN فایل‌های کش‌نشده را به‌جای سرور اصلی از نودهای Shield می‌گیرند و فقط Shield به سرور اصلی وصل می‌شود؛ درخواست‌های کمتری به سرور شما می‌رسد و نرخ کش بالاتر می‌رود. برای سایت‌های پربازدید یا سرور اصلی کم‌توان مناسب است.': 'CDN nodes fetch uncached files from the Shield nodes instead of your origin, and only the Shield connects to the origin; fewer requests reach your server and the cache hit ratio goes up. Good for busy sites or a low-powered origin.',
  'فقط وقتی اثر دارد که سکو نود Shield فعال داشته باشد. اگر نود Shield وجود نداشته باشد یا در دسترس نباشد، نودها مثل قبل مستقیم به سرور اصلی وصل می‌شوند و سایت قطع نمی‌شود.': 'Only takes effect when the platform has an active Shield node. If there is none, or it is unreachable, nodes connect directly to the origin as before and the site stays up.',
  'کلید کش': 'Cache key',
  'تعیین کنید چه چیزهایی نسخه‌های جداگانه در کش بسازند.': 'Decide what creates separate copies in the cache.',
  'نسخه جدا برای موبایل و دسکتاپ': 'Separate mobile and desktop versions',
  'فقط اگر سایت برای موبایل HTML متفاوتی می‌فرستد (نه صرفاً طراحی واکنش‌گرا) روشن کنید؛ وگرنه نرخ کش بی‌دلیل نصف می‌شود.': 'Turn on only if the site sends different HTML to mobile (not just responsive design); otherwise the cache hit ratio is halved for nothing.',
  'کوکی‌های مؤثر در کلید کش': 'Cookies that affect the cache key',
  'مقدار این کوکی‌ها بخشی از کلید کش می‌شود؛ مثلاً کوکی زبان یا واحد پول، تا هر زبان نسخه کش خودش را داشته باشد. کوکی ورود کاربر را اینجا نگذارید؛ برای آن «کوکی‌های عبور از کش» را به کار ببرید.': 'The values of these cookies become part of the cache key — e.g. a language or currency cookie, so each language gets its own cached copy. Do not put the login cookie here; use “Cache-bypass cookies” for that.',
  'پارامترهای مجاز Query String': 'Allowed query-string parameters',
  'اگر پر باشد فقط همین پارامترها در کلید کش لحاظ می‌شوند و بقیه (مثل utm_source یا fbclid) نادیده گرفته می‌شوند. خالی یعنی همه پارامترها.': 'If set, only these parameters are part of the cache key and the rest (such as utm_source or fbclid) are ignored. Empty means all parameters.',
  'تنظیمات کش': 'Cache settings',
  'کش CDN': 'CDN cache',
  'اگر خاموش باشد همه درخواست‌ها مستقیم به سرور اصلی می‌روند.': 'When off, every request goes straight to the origin server.',
  'سطح کش': 'Cache level',
  'استاندارد': 'Standard',
  'از هدر Cache-Control سرور پیروی می‌کند و فایل‌های ثابت (تصویر، CSS، JS) را کش می‌کند. برای اغلب سایت‌ها مناسب است.': 'Follows the server\'s Cache-Control header and caches static files (images, CSS, JS). Right for most sites.',
  'پیشنهادی': 'Recommended',
  'تهاجمی': 'Aggressive',
  'همه پاسخ‌های ۲۰۰ و ۳۰۱ کش می‌شوند و کوکی و Cache-Control نادیده گرفته می‌شود. فقط برای سایت‌های کاملاً ایستا.': 'All 200 and 301 responses are cached and cookies and Cache-Control are ignored. Only for fully static sites.',
  'در حالت تهاجمی صفحاتی مثل سبد خرید یا پنل کاربری هم ممکن است کش شوند و اطلاعات یک کاربر به دیگران نمایش داده شود. برای این مسیرها قانون صفحه «بدون کش» بسازید.': 'In aggressive mode, pages such as the cart or user dashboard may also be cached and one user\'s data shown to others. Create a “No cache” page rule for those paths.',
  'مدت نگهداری در CDN': 'CDN cache time',
  'فایل‌های ثابت حداکثر این مدت در سرورهای CDN می‌مانند.': 'Static files stay on the CDN servers for at most this long.',
  'مدت نگهداری در مرورگر': 'Browser cache time',
