  'طبق سرور': 'Per origin',
  '۰ یعنی هدر سرور اصلی دست نمی‌خورد.': '0 leaves the origin\'s header untouched.',
  'نادیده گرفتن Query String': 'Ignore query string',
  'آدرس‌های ‎?a=1 و ‎?a=2 یک نسخه کش مشترک می‌گیرند. اگر از ‎?v= برای نسخه‌بندی فایل‌ها استفاده می‌کنید خاموش بگذارید.': 'URLs ‎?a=1 and ‎?a=2 share one cached copy. Leave this off if you use ‎?v= to version files.',
  'اگر بازدیدکننده کوکی‌ای داشته باشد که نامش با یکی از این‌ها شروع شود، پاسخ از کش داده نمی‌شود (مثلاً کاربران واردشده).': 'If a visitor has a cookie whose name starts with one of these, the response is not served from cache (e.g. logged-in users).',
  'همیشه آنلاین': 'Always online',
  'اگر سرور اصلی خطا بدهد یا در دسترس نباشد، آخرین نسخه کش‌شده نمایش داده می‌شود.': 'If the origin returns an error or is unreachable, the last cached copy is served.',
  'حالت توسعه': 'Development mode',
  'کش موقتاً خاموش می‌شود تا تغییرات سایت فوراً دیده شوند. بعد از پایان کار خاموشش کنید.': 'Caching is paused so site changes show up immediately. Turn it off when you are done.',
