  'preload را فقط وقتی فعال کنید که قصد ثبت دامنه در فهرست preload مرورگرها را دارید. خروج از این فهرست ماه‌ها طول می‌کشد و در این مدت هر زیردامنه بدون HTTPS از دسترس خارج می‌شود.': 'Only enable preload if you intend to submit the domain to the browsers\' preload list. Leaving the list takes months, and meanwhile any subdomain without HTTPS becomes unreachable.',
