  'امن‌تر': 'More secure',
  'اگر سرور اصلی (یا وردپرس) خودش به HTTPS ریدایرکت می‌کند، با این حالت خطای «تعداد ریدایرکت زیاد» می‌گیرید.': 'If the origin (or WordPress) itself redirects to HTTPS, this mode gives you a “too many redirects” error.',
