  'نسل جدید پروتکل HTTP روی QUIC': 'The new generation of HTTP over QUIC',
  'روی اینترنت موبایل و شبکه‌های ناپایدار، صفحات سریع‌تر و پایدارتر بارگذاری می‌شوند. مرورگرهایی که پشتیبانی می‌کنند خودکار از آن استفاده می‌کنند و بقیه مثل قبل با HTTP/2 وصل می‌شوند.': 'Pages load faster and more reliably on mobile internet and unstable networks. Browsers that support it use it automatically; the rest connect over HTTP/2 as before.',
