  'نشانی سرویس حداکثر ۵۱۲ نویسه می‌تواند باشد.': 'The service endpoint can be at most 512 characters.',
  'نشانی سرویس باید با https:// شروع شود (اتصال رمزنگاری‌شده الزامی است).': 'The service endpoint must start with https:// (an encrypted connection is required).',
  'نشانی سرویس معتبر نیست؛ مثل https://s3.example.com بنویسید (بدون نام کاربری، ? یا #).': 'The service endpoint is invalid; write it like https://s3.example.com (no username, ? or #).',
  'ناحیه (region) فقط حروف انگلیسی، عدد، - و _ (حداکثر ۶۴ نویسه) است؛ مثلاً us-east-1.': 'The region is English letters, digits, - and _ only (max 64 characters); e.g. us-east-1.',
  'نام باکت طبق قواعد S3: ۳ تا ۶۳ نویسه، فقط حروف کوچک لاتین، عدد، نقطه و خط تیره، با حرف یا عدد شروع و تمام شود (و شبیه آی‌پی نباشد).': 'Bucket name per S3 rules: 3 to 63 characters, only lowercase Latin letters, digits, dots and hyphens, starting and ending with a letter or digit (and not looking like an IP).',
  'پیشوند حداکثر ۱۲۸ نویسه می‌تواند باشد.': 'The prefix can be at most 128 characters.',
  'پیشوند فقط حروف لاتین، عدد و نویسه‌های / _ . - را می‌پذیرد و نباید .. داشته باشد.': 'The prefix only accepts Latin letters, digits and the characters / _ . - and must not contain ..',
  'کلید دسترسی حداکثر ۱۲۸ نویسه می‌تواند باشد.': 'The access key can be at most 128 characters.',
  'کلید دسترسی فقط نویسه‌های چاپ‌پذیر انگلیسی و بدون فاصله است.': 'The access key is printable English characters only, without spaces.',
  'کلید مخفی حداکثر ۲۵۶ نویسه می‌تواند باشد.': 'The secret key can be at most 256 characters.',
  'کلید مخفی فقط نویسه‌های چاپ‌پذیر انگلیسی و بدون فاصله است.': 'The secret key is printable English characters only, without spaces.',
  'نرخ نمونه‌برداری باید بین ۱٪ و ۱۰۰٪ باشد.': 'The sampling rate must be between 1% and 100%.',
  'برای روشن کردن ارسال لاگ، نشانی سرویس S3 را وارد کنید.': 'To turn on log shipping, enter the S3 service endpoint.',
  'برای روشن کردن ارسال لاگ، نام باکت را وارد کنید.': 'To turn on log shipping, enter the bucket name.',
  'برای روشن کردن ارسال لاگ، کلید دسترسی (Access Key) را وارد کنید.': 'To turn on log shipping, enter the access key.',
  'برای روشن کردن ارسال لاگ، کلید مخفی (Secret Key) را وارد کنید.': 'To turn on log shipping, enter the secret key.',
  '٪ درخواست‌ها': '% of requests',
  'نرخ نمونه‌برداری (درصد)': 'Sampling rate (percent)',
  'فقط این درصد از درخواست‌ها ارسال می‌شود؛ برای سایت‌های پربازدید، نمونه‌برداری حجم و هزینهٔ ذخیره‌سازی را کم می‌کند. ۱۰۰٪ یعنی همهٔ درخواست‌ها.': 'Only this percentage of requests is shipped; for busy sites, sampling cuts storage volume and cost. 100% means every request.',
  'کلید مخفی (Secret Key)': 'Secret key',
  'ذخیره شده — برای تغییر مقدار جدید وارد کنید': 'Saved — enter a new value to change it',
  'کلید مخفی سرویس S3': 'S3 service secret key',
  'کلید فعلی رمزنگاری‌شده نگهداری می‌شود و هرگز نمایش داده نمی‌شود؛ خالی بگذارید تا همان بماند.': 'The current key is stored encrypted and never shown; leave empty to keep it.',
  'فقط یک‌بار فرستاده و رمزنگاری‌شده نگهداری می‌شود؛ پس از ذخیره دیگر نمایش داده نمی‌شود.': 'Sent only once and stored encrypted; it is not shown again after saving.',
  'ذخیره شده': 'Saved',
  'مقصد (فضای ذخیره‌سازی سازگار با S3)': 'Destination (S3-compatible storage)',
  'هر ساعت یک فایل فشرده (gzip، هر خط یک رکورد JSON) در باکت شما بارگذاری می‌شود.': 'Every hour a compressed file (gzip, one JSON record per line) is uploaded to your bucket.',
  'نشانی سرویس (Endpoint)': 'Service endpoint',
  'نشانی HTTPS سرویس ذخیره‌سازی (AWS S3، آروان، MinIO و …). باید به آی‌پی عمومی برسد.': 'The HTTPS endpoint of the storage service (AWS S3, Arvan, MinIO, …). It must be reachable on a public IP.',
  'ناحیه (Region)': 'Region',
  'اگر سرویس شما ناحیه ندارد، همان us-east-1 را بگذارید.': 'If your service has no regions, leave us-east-1.',
  'نام باکت (Bucket)': 'Bucket name',
  'پیشوند مسیر فایل‌ها (اختیاری)': 'File path prefix (optional)',
  'نمونهٔ مسیر فایل:': 'Sample file path:',
  'کلید دسترسی (Access Key)': 'Access key',
  'برای امنیت بیشتر یک کلید جداگانه بسازید که فقط اجازهٔ «نوشتن» (PutObject) در همین باکت/پیشوند را داشته باشد.': 'For extra security, create a separate key that is only allowed to “write” (PutObject) to this bucket/prefix.',
  'حریم خصوصی و نمونه‌برداری': 'Privacy and sampling',
  'ناشناس‌سازی آی‌پی بازدیدکنندگان (پیشنهادی)': 'Anonymize visitor IPs (recommended)',
  'پیش از ارسال، بخش آخر آی‌پی حذف می‌شود (IPv4: هشت بیت آخر صفر می‌شود، مثلاً 5.160.12.0؛ IPv6: فقط ۴۸ بیت اول می‌ماند). آمار کشور و رفتار کلی حفظ می‌شود ولی بازدیدکنندهٔ مشخصی قابل شناسایی نیست.': 'Before shipping, the last part of the IP is removed (IPv4: the last eight bits are zeroed, e.g. 5.160.12.0; IPv6: only the first 48 bits are kept). Country statistics and overall behaviour are kept, but no individual visitor can be identified.',
  'آی‌پی کامل بازدیدکنندگان دادهٔ شخصی است. اگر خاموشش می‌کنید، طبق قوانین حریم خصوصی و سیاست سایت خودتان با آن رفتار کنید و دسترسی به باکت را محدود نگه دارید.': 'Visitors\' full IPs are personal data. If you turn this off, handle them according to privacy law and your own site\'s policy, and keep access to the bucket restricted.',
  'ارسال لاگ دسترسی': 'Access log shipping',
  'ارسال لاگ‌های دسترسی این سایت به باکت من': 'Ship this site\'s access logs to my bucket',
  'سرورهای CDN رکورد درخواست‌ها را جمع می‌کنند و هر ساعت در باکت شما بارگذاری می‌شود. برای روشن کردن، نشانی، باکت و هر دو کلید لازم است.': 'The CDN servers collect request records and upload them to your bucket every hour. To turn it on, the endpoint, bucket and both keys are required.',
