  'رکوردهای کنارگذاشته به‌خاطر سقف ساعتی هر سایت یا خطای طولانی بارگذاری (بیش از ۷۲ ساعت) ارسال نشده‌اند.': 'Dropped records were not shipped because of the per-site hourly cap or a prolonged upload error (over 72 hours).',
  'آخرین خطا': 'Last error',
  'بارگذاری‌های ناموفق هر ۱۰ دقیقه دوباره امتحان می‌شوند؛ نشانی، باکت و کلیدها را بررسی کنید.': 'Failed uploads are retried every 10 minutes; check the endpoint, bucket and keys.',
