  'بارگذاری ناموفق نگه داشته و هر ۱۰ دقیقه دوباره امتحان می‌شود؛ داده‌ای که ۷۲ ساعت بارگذاری نشود کنار گذاشته می‌شود.': 'A failed upload is kept and retried every 10 minutes; data not uploaded within 72 hours is dropped.',
