  'همین حالا آن را کپی کنید و در تنظیمات سرور خود (مثلاً متغیر محیطی PCDN_WEBHOOK_SECRET) ذخیره کنید؛ اگر گم شود باید «تعویض کلید امضا» بزنید.': 'Copy it now and store it in your server\'s settings (e.g. the PCDN_WEBHOOK_SECRET environment variable); if it is lost you must use “Rotate signing key”.',
  'کلید قبلی باطل شد؛ از این پس همهٔ ارسال‌ها با کلید جدید امضا می‌شوند.': 'The previous key is revoked; from now on every delivery is signed with the new key.',
