  'درخواست POST با بدنهٔ JSON و امضای X-Pcdn-Signature به این نشانی فرستاده می‌شود. ریدایرکت دنبال نمی‌شود و پاسخ باید ظرف ۱۰ ثانیه 2xx باشد.': 'A POST request with a JSON body and an X-Pcdn-Signature signature is sent to this URL. Redirects are not followed and the response must be 2xx within 10 seconds.',
