  'هنوز وب‌هوکی ندارید': 'No webhooks yet',
  'با وب‌هوک، رویدادهای مهم سایت (پاکسازی کش، صدور یا خطای SSL، هشدار و اتمام ترافیک، تعلیق، حمله) بی‌درنگ به سرور، اسلک یا سیستم پایش شما فرستاده می‌شود.': 'With a webhook, important site events (cache purge, SSL issued or failed, traffic warning and exhaustion, suspension, attack) are sent instantly to your server, Slack or monitoring system.',
