  'ارسال‌های اخیر': 'Recent deliveries',
  '۵۰ ارسال آخر در ۷ روز گذشته؛ جدیدترین در بالا': 'Last 50 deliveries in the past 7 days; newest first',
  'دریافت ارسال‌ها ممکن نشد': 'Could not load deliveries',
