  'پس از اولین رویداد یا «ارسال آزمایشی»، نتیجهٔ هر ارسال (کد پاسخ، تعداد تلاش و خطا) اینجا دیده می‌شود.': 'After the first event or a “Send test”, each delivery\'s result (response code, attempts and error) shows up here.',
