  'ارسال‌های اخیر وب‌هوک': 'Recent webhook deliveries',
  'ارسال ناموفق پس از ۱ دقیقه، ۵ دقیقه، ۳۰ دقیقه، ۲ ساعت، ۶ ساعت و سپس هر ۶ ساعت تا ۲۴ ساعت دوباره امتحان می‌شود.': 'Failed deliveries are retried after 1 minute, 5 minutes, 30 minutes, 2 hours, 6 hours and then every 6 hours for up to 24 hours.',
  'راهنمای بررسی امضا': 'Signature verification guide',
  'مطمئن شوید هر درخواست واقعاً از CDN آمده و در مسیر تغییر نکرده است': 'Make sure each request really came from the CDN and was not altered on the way',
  'زبان نمونه کد': 'Sample code language',
  'هر ارسال یک درخواست POST با بدنهٔ JSON است ({id, type, created_at, site, data}) و این هدرها را دارد:': 'Each delivery is a POST request with a JSON body ({id, type, created_at, site, data}) and these headers:',
  '— نوع رویداد (مثل': '— event type (e.g.',
  '— شناسهٔ این ارسال (برای جلوگیری از پردازش تکراری)': '— the ID of this delivery (to avoid processing it twice)',
  '— زمان ارسال به ثانیهٔ یونیکس': '— delivery time in Unix seconds',
  'به‌صورت hex': 'in hex',
  'بدنهٔ خام درخواست را همان‌طور که رسیده بخوانید (پیش از هر تبدیل JSON).': 'Read the raw request body exactly as received (before any JSON parsing).',
  'رشتهٔ «timestamp + نقطه + بدنهٔ خام» را با کلید امضا (whsec_…) با HMAC-SHA256 امضا کنید و پیشوند sha256= بگذارید.': 'Sign the string “timestamp + dot + raw body” with HMAC-SHA256 using the signing key (whsec_…) and prefix it with sha256=.',
  'حاصل را با هدر X-Pcdn-Signature با مقایسهٔ زمان‌ثابت (hash_equals / timingSafeEqual / compare_digest) مقایسه کنید.': 'Compare the result with the X-Pcdn-Signature header using a constant-time comparison (hash_equals / timingSafeEqual / compare_digest).',
  'درخواستی را که timestamp آن بیش از ۵ دقیقه با ساعت سرور شما فاصله دارد رد کنید (جلوگیری از بازپخش).': 'Reject requests whose timestamp is more than 5 minutes from your server\'s clock (replay protection).',
  'سریع (کمتر از ۱۰ ثانیه) با کد 2xx پاسخ دهید و کار سنگین را در پس‌زمینه انجام دهید؛ در غیر این صورت ارسال دوباره تکرار می‌شود.': 'Respond quickly (under 10 seconds) with a 2xx code and do heavy work in the background; otherwise the delivery is retried.',
  'نمونهٔ بدنهٔ یک رویداد (هدر X-Pcdn-Event: ssl.issued):': 'Sample event body (header X-Pcdn-Event: ssl.issued):',
  'ساعت سرور خود را با NTP همگام نگه دارید؛ اختلاف ساعت بیش از ۵ دقیقه باعث رد شدن همهٔ ارسال‌ها می‌شود.': 'Keep your server\'s clock in sync with NTP; a clock skew of more than 5 minutes rejects every delivery.',
