  'موفقیت درخواست‌ها': 'Request success',
  'بدون احتساب خطاهای سرور اصلی شما': 'Excluding errors from your own origin',
  'آپتایم نودهای لبه': 'Edge node uptime',
  'میانگین پایش نودهای گروه سایت': 'Average monitoring of the site\'s node group',
  'خطای 5xx تولیدشده توسط خود CDN': '5xx errors produced by the CDN itself',
  'روزبه‌روز': 'Day by day',
  'برای این ماه داده‌ای ثبت نشده است': 'No data recorded for this month',
  'گزارش از روزی که سایت ترافیک داشته یا نودها پایش شده‌اند ساخته می‌شود.': 'The report is built from days on which the site had traffic or the nodes were monitored.',
  'تاریخ': 'Date',
  'آپتایم لبه': 'Edge uptime',
  'دسترس‌پذیری روزانه': 'Daily availability',
  'نحوهٔ محاسبه': 'How it is calculated',
  'موفقیت درخواست‌ها = ۱۰۰ × (۱ − خطاهای سکو ÷ کل درخواست‌ها). خطای سکو یعنی پاسخ 5xx که خود CDN ساخته است؛ خطاهای سرور اصلی شما و درخواست‌هایی که فایروال، WAF یا محدودیت نرخ مسدود کرده‌اند حساب نمی‌شوند.': 'Request success = 100 × (1 − platform errors ÷ all requests). A platform error is a 5xx response produced by the CDN itself; errors from your origin and requests blocked by the firewall, WAF or rate limiting are not counted.',
  'آپتایم لبه = میانگین نتیجهٔ پایش نودهای گروهی که به سایت شما سرویس می‌دهند.': 'Edge uptime = the average monitoring result of the node group that serves your site.',
  'دسترس‌پذیری = کمترِ این دو مقدار (هر کدام که داده داشته باشد). ماهی که هیچ داده‌ای ندارد «داده‌ای نیست» نشان داده می‌شود.': 'Availability = the lower of the two (whichever has data). A month with no data at all shows “No data”.',
  'ماه‌ها به وقت UTC (ماه میلادی) حساب می‌شوند.': 'Months are counted in UTC (Gregorian months).',
  'ارسال لاگ': 'Log shipping',
  'لاگ درخواست‌های این سایت را هر ساعت به باکت S3 (یا سرویس سازگار) خودتان بفرستید تا برای تحلیل، نگهداری یا SIEM در اختیار داشته باشید.': 'Ship this site\'s request logs every hour to your own S3 bucket (or a compatible service) for analysis, retention or a SIEM.',
  'سرورهای CDN رکورد هر درخواست (زمان، آی‌پی، مسیر، کد پاسخ، حجم، وضعیت کش، کشور و …) را جمع و هر ساعت به‌صورت فایل فشرده در باکت شما بارگذاری می‌کنند.': 'The CDN servers collect a record of each request (time, IP, path, response code, size, cache status, country, …) and upload it to your bucket every hour as a compressed file.',
  'وقتی به لاگ کامل دسترسی برای تحلیل ترافیک، بررسی امنیتی یا نگهداری طبق مقررات نیاز دارید.': 'When you need full logs for traffic analysis, security review or regulatory retention.',
  'ناشناس‌سازی آی‌پی روشن، نمونه‌برداری ۱۰۰٪ برای سایت‌های کوچک و کمتر برای سایت‌های پربازدید، و یک کلید S3 که فقط اجازهٔ نوشتن در همین باکت را دارد.': 'IP anonymization on, 100% sampling for small sites and less for busy ones, and an S3 key that can only write to this bucket.',
  'کلیدی با دسترسی کامل به همهٔ باکت‌ها.': 'A key with full access to every bucket.',
  'نشانی سرویس با http:// (فقط HTTPS پذیرفته می‌شود).': 'A service endpoint with http:// (only HTTPS is accepted).',
  'خاموش کردن ناشناس‌سازی بدون نیاز واقعی به آی‌پی کامل.': 'Turning anonymization off without a real need for full IPs.',
  'با ارتقای پلن می‌توانید لاگ دسترسی سایت را به فضای ذخیره‌سازی خودتان بفرستید.': 'Upgrade your plan to ship the site\'s access logs to your own storage.',
  'رویدادهای مهم سایت (پاکسازی کش، SSL، هشدار و اتمام ترافیک، تعلیق، حمله) را بی‌درنگ با درخواست امضاشده به سرور یا ابزار خودتان بفرستید.': 'Send important site events (cache purge, SSL, traffic warning and exhaustion, suspension, attack) instantly to your own server or tool as a signed request.',
  'وب‌هوک یک درخواست HTTPS با بدنهٔ JSON است که هنگام رخ دادن رویداد به نشانی شما فرستاده می‌شود و با کلید مخصوص همان وب‌هوک امضا شده است.': 'A webhook is an HTTPS request with a JSON body sent to your URL when an event happens, signed with that webhook\'s own key.',
  'برای اعلان در اسلک/تلگرام از راه سرور واسط، ثبت در سیستم پایش، یا خودکارسازی (مثلاً پاکسازی کش برنامه پس از پاکسازی CDN).': 'For notifications on Slack/Telegram through a relay server, logging in a monitoring system, or automation (e.g. purging the app cache after a CDN purge).',
  'همیشه امضا و timestamp را بررسی کنید، سریع پاسخ 2xx بدهید و رویدادها را بر اساس id یکتا پردازش کنید.': 'Always check the signature and timestamp, respond 2xx quickly, and process events by their unique id.',
  'نادیده گرفتن بررسی امضا (هر کسی می‌تواند به نشانی شما درخواست بفرستد).': 'Skipping signature checks (anyone can send requests to your URL).',
  'پاسخ کند یا ریدایرکت (ارسال ناموفق حساب می‌شود و تکرار می‌شود).': 'A slow response or a redirect (counted as a failed delivery and retried).',
  'ذخیره نکردن کلید امضا هنگام نمایش (فقط یک بار نشان داده می‌شود).': 'Not saving the signing key when it is shown (it is shown only once).',
  'با ارتقای پلن می‌توانید رویدادهای سایت را با وب‌هوک به سیستم‌های خودتان بفرستید.': 'Upgrade your plan to send site events to your own systems with webhooks.',
  'گزارش SLA': 'SLA report',
  'دسترس‌پذیری ماهانهٔ سایت روی CDN در مقایسه با هدف SLA پلن، به‌همراه جزئیات روزانه، خروجی CSV و نسخهٔ چاپی.': 'The site\'s monthly availability on the CDN compared with the plan\'s SLA target, with daily details, CSV export and a printable version.',
