  'پورتی روی CDN که ترافیک آن به سرور شما می‌رسد.': 'A port on the CDN whose traffic reaches your server.',
  'کاربران به این پورت روی نشانی CDN وصل می‌شوند. خالی بگذارید تا هنگام ذخیره اولین پورت آزاد داده شود؛ یا پورتی در بازهٔ': 'Users connect to this port on the CDN address. Leave it empty to get the first free port when saving, or give a port in the range',
  'بدهید (اگر سرویس دیگری آن را گرفته باشد هنگام ذخیره خبر می‌دهیم).': '(if another service has taken it, we\'ll tell you when saving).',
  'تعیین خودکار': 'Automatic',
  'پورت تصادفی': 'Random port',
  'برای بازی‌های TCP، SSH، پایگاه داده، MQTT، RDP و هر سرویس اتصال‌گرا.': 'For TCP games, SSH, databases, MQTT, RDP and any connection-oriented service.',
  'برای بازی‌های UDP، DNS، VoIP و پخش زنده؛ PROXY protocol ندارد.': 'For UDP games, DNS, VoIP and live streaming; no PROXY protocol.',
  'مهلت بیکاری اتصال': 'Connection idle timeout',
  'اتصالی که این مدت هیچ داده‌ای رد و بدل نکند بسته می‌شود (۱۰ تا ۳۶۰۰؛ پیش‌فرض ۳۰۰).': 'A connection that exchanges no data for this long is closed (10 to 3600; default 300).',
  'آدرس سرور مقصد': 'Destination server address',
  'آی‌پی عمومی یا نام دامنهٔ سرور شما (نه آی‌پی داخلی).': 'Your server\'s public IP or domain name (not an internal IP).',
  'پورت سرور مقصد': 'Destination server port',
  'روشن کنید تا سرور شما آی‌پی واقعی کاربر را ببیند (هدر PROXY protocol نسخهٔ ۱)؛ فقط اگر نرم‌افزار سرور آن را پشتیبانی می‌کند و روشن کرده‌اید (وگرنه اتصال‌ها خراب می‌شوند).': 'Turn on so your server sees the user\'s real IP (PROXY protocol v1 header); only if your server software supports it and has it enabled (otherwise connections break).',
  'در UDP آی‌پی کاربر به سرور شما نمی‌رسد و سرور آی‌پی نودهای CDN را می‌بیند.': 'With UDP the user\'s IP does not reach your server; it sees the CDN nodes\' IPs.',
  'فقط این آی‌پی‌ها (اختیاری)': 'Only these IPs (optional)',
  'خالی = همه می‌توانند وصل شوند. با آی‌پی یا بازهٔ CIDR دسترسی را محدود کنید (مثلاً فقط دفتر شما). با Enter یا کاما اضافه کنید.': 'Empty = anyone can connect. Restrict access with an IP or CIDR range (e.g. only your office). Press Enter or comma to add.',
  'برنامهٔ غیرفعال نگه داشته می‌شود ولی پورت آن روی نودها بسته است.': 'A disabled app is kept but its port is closed on the nodes.',
  'تغییرات برنامه اعمال شد؛ برای ثبت «ذخیره» را بزنید.': 'App changes applied; press “Save” to store them.',
  'برنامه به فهرست اضافه شد؛ برای ثبت «ذخیره» را بزنید.': 'App added to the list; press “Save” to store it.',
  'برنامهٔ جدید': 'New app',
  'برنامهٔ پلن رسیده‌اید': 'apps in your plan',
  'برنامه‌های TCP/UDP': 'TCP/UDP apps',
  'هر برنامه یک پورت روی CDN است که ترافیک را به سرور شما می‌رساند.': 'Each app is a port on the CDN that carries traffic to your server.',
  'هنوز برنامه‌ای نساخته‌اید': 'No apps yet',
  'برای سرویس‌های غیر وب (سرور بازی، SSH، پایگاه داده، MQTT، VoIP) یک پورت TCP یا UDP روی CDN بسازید تا آی‌پی سرورتان پنهان بماند و ترافیک از نودهای CDN عبور کند.': 'For non-web services (game server, SSH, database, MQTT, VoIP) create a TCP or UDP port on the CDN so your server IP stays hidden and traffic flows through the CDN nodes.',
