  'شروع شود؛ فقط حروف انگلیسی، عدد و': '; English letters, digits and',
  '. هر چه طولانی‌تر و تصادفی‌تر، امن‌تر.': 'only. The longer and more random, the safer.',
  'در gRPC همین مسیر بدون': 'In gRPC this path without the leading',
  'اول، serviceName است.': 'is the serviceName.',
  'ساخت مسیر تصادفی': 'Generate random path',
  'سرور مقصد (سرور VPN شما)': 'Destination server (your VPN server)',
  'به آدرس و پورت رکورد پروکسی‌شده (و پروتکل «اتصال به سرور اصلی» در SSL) وصل می‌شود.': 'Connects to the proxied record\'s address and port (and the “Connection to the origin” protocol in SSL).',
  'آدرس و پورت دلخواه': 'Custom address and port',
  'مثلاً سرور جداگانه Xray روی پورت ۲۰۵۳. پیشنهادی وقتی روی همین سرور سایت هم دارید.': 'E.g. a separate Xray server on port 2053. Recommended when the same server also hosts the site.',
  'استخر توزیع بار': 'Load-balancing pool',
  'بین چند سرور VPN تقسیم می‌شود و سرور خراب کنار گذاشته می‌شود.': 'Split between several VPN servers, and a failed server is taken out.',
  'ابتدا در بخش «توزیع بار» یک استخر بسازید (در پلن شما:': 'First create a pool under “Load balancing” (in your plan:',
  'IPv4، IPv6 یا نام میزبان.': 'IPv4, IPv6 or host name.',
