  'معمولاً خاموش: CDN خودش TLS بازدیدکننده را باز می‌کند و سرور Xray بدون TLS گوش می‌دهد (ساده‌تر، بدون نیاز به گواهی روی سرور).': 'Usually off: the CDN terminates the visitor\'s TLS and the Xray server listens without TLS (simpler, no certificate needed on the server).',
  'SNI (اختیاری)': 'SNI (optional)',
  'خالی = نام دامنه سایت. باید با گواهی سرور شما بخواند.': 'Empty = the site\'s domain name. It must match your server\'s certificate.',
  'بررسی اعتبار گواهی سرور': 'Verify the server certificate',
  'فقط اگر گواهی معتبر (مثلاً Let\'s Encrypt) روی سرور دارید.': 'Only if the server has a valid certificate (e.g. Let\'s Encrypt).',
  'سرور)': 'server(s))',
  'هنوز استخری ندارید.': 'You have no pools yet.',
  'ساخت استخر در «توزیع بار»': 'Create a pool under “Load balancing”',
  'برای gRPC مسیر تک‌بخشی (بدون / میانی) بگذارید؛ بعضی کلاینت‌ها serviceName چندبخشی را پشتیبانی نمی‌کنند.': 'For gRPC use a single-segment path (no / in the middle); some clients don\'t support multi-segment serviceNames.',
  'حالت h2: سرور شما باید HTTP/2 بدون TLS (h2c) یا با TLS را بپذیرد؛ در Xray، ورودی XHTTP با حالت stream-one.': 'h2 mode: your server must accept HTTP/2 without TLS (h2c) or with TLS; in Xray, an XHTTP inbound in stream-one mode.',
  'مسیر باید با / شروع شود و فقط حروف انگلیسی، عدد و . _ ~ / - داشته باشد (حداکثر ۲۰۰ کاراکتر).': 'The path must start with / and contain only English letters, digits and . _ ~ / - (max 200 characters).',
  'مسیرهای /__pcdn رزرو شده‌اند.': '/__pcdn paths are reserved.',
  'این مسیر قبلاً برای مسیر دیگری استفاده شده است.': 'This path is already used by another path.',
  'پورت باید عددی بین ۱ و ۶۵۵۳۵ باشد.': 'The port must be a number between 1 and 65535.',
