  'پشتیبانی': 'Support of',
  'به نسخه‌ی برنامه بستگی دارد؛ اگر وصل نشد برنامه را به‌روز کنید یا از مسیر gRPC / WebSocket استفاده کنید.': 'depends on the app version; if it doesn\'t connect, update the app or use a gRPC / WebSocket path.',
