  '۱. لینک اشتراک برای کلاینت': '1. Share link for the client',
  'در v2rayNG، v2rayN، Hiddify، Streisand یا NekoBox: لینک را کپی و «Import from clipboard» را بزنید یا QR را اسکن کنید.': 'In v2rayNG, v2rayN, Hiddify, Streisand or NekoBox: copy the link and tap “Import from clipboard”, or scan the QR code.',
  'کپی لینک اشتراک': 'Copy share link',
  'کپی لینک': 'Copy link',
  'لینک کپی شد': 'Link copied',
  'XHTTP فقط در کلاینت‌های با هسته Xray (v2rayNG و v2rayN نسخه‌های جدید، Hiddify با هسته Xray، Streisand) کار می‌کند.': 'XHTTP only works in Xray-core clients (recent v2rayNG and v2rayN, Hiddify with the Xray core, Streisand).',
  'لینک برای QR بیش از حد طولانی است.': 'The link is too long for a QR code.',
  '۲. تنظیم سرور شما (Xray)': '2. Configuring your server (Xray)',
