  'را اجرا کنید.': '.',
  'چون اتصال CDN به سرور با TLS است، مسیر گواهی و کلید را اصلاح کنید.': 'Because the CDN connects to the server with TLS, fix the certificate and key paths.',
  'ورودی بدون TLS گوش می‌دهد؛ رمزنگاری بین بازدیدکننده و CDN انجام می‌شود.': 'The inbound listens without TLS; encryption happens between the visitor and the CDN.',
  'config.json — Xray (سرور)': 'config.json — Xray (server)',
  'مقصد این مسیر «همان سرور اصلی سایت» است، یعنی پورت': 'This path\'s destination is “The site\'s own origin”, i.e. port',
  '. اگر وب‌سرور (nginx/Apache) روی این پورت است، یا مسیر را در وب‌سرور به Xray پاس دهید یا مقصد مسیر را «آدرس و پورت دلخواه» بگذارید.': '. If a web server (nginx/Apache) is on that port, either pass the path through the web server to Xray or set the path\'s destination to “Custom address and port”.',
  'راهنما': 'Guide',
  '۳. کلاینت sing-box (اختیاری)': '3. sing-box client (optional)',
  'sing-box از XHTTP پشتیبانی نمی‌کند؛ برای این مسیر از لینک اشتراک در کلاینت‌های مبتنی بر Xray استفاده کنید.': 'sing-box does not support XHTTP; for this path use the share link in Xray-based clients.',
