  'تونل پس از فعال شدن سایت روی CDN (تأیید نیم‌سرورها) کار می‌کند؛ تا آن زمان می‌توانید مسیرها را آماده کنید.': 'The tunnel works once the site is active on the CDN (nameservers verified); until then you can prepare the paths.',
