  'سقف سرعت هر اتصال': 'Speed cap per connection',
  'فعلاً اعمال نمی‌شود: محدودسازی سرعت روی جریان‌های تونل (gRPC، WebSocket و …) هنوز در نودها پشتیبانی نمی‌شود.': 'Not applied for now: speed limiting on tunnel streams (gRPC, WebSocket, …) is not yet supported on the nodes.',
  'اتصالی که این مدت هیچ داده‌ای نداشته باشد بسته می‌شود (۶۰ ثانیه تا ۱ روز).': 'A connection with no data for this long is closed (60 seconds to 1 day).',
  'حداکثر اتصال همزمان هر IP': 'Max concurrent connections per IP',
  '۰ یعنی نامحدود (روی هر نود). هر جریان WebSocket یا gRPC یک اتصال حساب می‌شود و کلاینت‌ها چند جریان همزمان باز می‌کنند؛ کمتر از ۱۰ نگذارید. اضافه‌ها خطای ۴۲۹ می‌گیرند.': '0 means unlimited (per node). Each WebSocket or gRPC stream counts as a connection and clients open several streams at once; don\'t set it below 10. Extra connections get a 429 error.',
  'کشورهای مجاز': 'Allowed countries',
  'خالی = همه. کاربران کشورهای دیگر روی مسیرهای تونل خطای ۴۰۳ می‌گیرند (کد دوحرفی ISO، مثل IR).': 'Empty = all. Users from other countries get a 403 error on the tunnel paths (two-letter ISO code, like IR).',
  'بقیه مسیرهای دامنه': 'Other paths of the domain',
  'صفحه استتار (decoy) یعنی هر کس دامنه را در مرورگر باز کند یک سایت ساده و بی‌خطر می‌بیند، نه خطا یا سرور VPN شما.': 'A camouflage (decoy) page means anyone opening the domain in a browser sees a simple, harmless site, not an error or your VPN server.',
  'تغییرات ذخیره شد و تا چند ثانیه روی همه نودهای تونل اعمال می‌شود.': 'Changes saved; they reach all tunnel nodes within a few seconds.',
  'راه‌اندازی در ۴ قدم': 'Setup in 4 steps',
  'در «رکوردها» یک رکورد A (مثلاً vpn) به آی‌پی سرور VPN بسازید و پروکسی را روشن کنید.': 'Under “Records” create an A record (e.g. vpn) to the VPN server\'s IP and turn the proxy on.',
  'تونل را روشن کنید، یک مسیر با پروتکل gRPC بسازید و ذخیره کنید.': 'Turn the tunnel on, create a path with the gRPC protocol and save.',
  'از «پیکربندی آماده» فایل config.json سرور Xray را کپی و Xray را راه‌اندازی کنید.': 'From “Ready config” copy the Xray server\'s config.json and start Xray.',
  'لینک اشتراک یا QR را در کلاینت (v2rayNG، v2rayN، Hiddify) وارد و وصل شوید.': 'Import the share link or QR code into the client (v2rayNG, v2rayN, Hiddify) and connect.',
  'آموزش کامل و عیب‌یابی': 'Full tutorial and troubleshooting',
  'تونل / VPN': 'Tunnel / VPN',
  'تونل / VPN پشت CDN': 'Tunnel / VPN behind the CDN',
  'Xray / V2Ray / sing-box را با gRPC، XHTTP، WebSocket، HTTPUpgrade یا HTTP/2 از طریق نودهای داخل ایران به سرور خود برسانید.': 'Carry Xray / V2Ray / sing-box to your server over gRPC, XHTTP, WebSocket, HTTPUpgrade or HTTP/2 through nodes inside Iran.',
  'کاربران به نودهای CDN (داخل ایران) وصل می‌شوند و CDN جریان‌های طولانی را بدون کش و بافر به سرور VPN شما (مثلاً در خارج) می‌رساند؛ آی‌پی سرور شما پنهان می‌ماند.': 'Users connect to the CDN nodes (inside Iran) and the CDN carries long-lived streams without caching or buffering to your VPN server (e.g. abroad); your server\'s IP stays hidden.',
  'وقتی سرور Xray/V2Ray دارید و می‌خواهید اتصال کاربران پایدارتر باشد یا آی‌پی سرور مستقیم فیلتر یا کند شده است.': 'When you have an Xray/V2Ray server and want users\' connections to be more stable, or the server IP itself is filtered or slow.',
  'پروتکل gRPC، مسیر تصادفی طولانی، صفحه استتار برای بقیه مسیرها و در صورت نیاز «فقط ایران».': 'The gRPC protocol, a long random path, the camouflage page for other paths and “Iran only” if needed.',
  'پروکسی نکردن رکورد DNS (ترافیک مستقیم به سرور می‌رود).': 'Not proxying the DNS record (traffic goes straight to the server).',
  'روشن کردن TLS روی ورودی Xray در حالی که «اتصال با TLS» در مسیر خاموش است (یا برعکس).': 'Turning on TLS on the Xray inbound while “Connect with TLS” is off on the path (or the other way round).',
  'مسیر یا UUID متفاوت در سرور و کلاینت.': 'A different path or UUID on the server and the client.',
  'بستن آی‌پی‌های CDN در فایروال سرور.': 'Blocking the CDN IPs in the server firewall.',
  'تونل / VPN در همه پلن‌های CDN گنجانده شده است. سرور Xray / V2Ray خود را پشت CDN و نودهای داخل ایران قرار دهید: اتصال پایدارتر، آی‌پی پنهان و بدون نیاز به دامنه یا سرور اضافه. اگر این بخش فعال نیست، پلن سرویس را به‌روزرسانی کنید یا با پشتیبانی تماس بگیرید.': 'Tunnel / VPN is included in every CDN plan. Put your Xray / V2Ray server behind the CDN and its nodes inside Iran: a more stable connection, a hidden IP, and no extra domain or server needed. If this section isn\'t active, update the service\'s plan or contact support.',
