  'بدون ترافیک': 'no traffic',
  'اتصال به سرور شما رد شد': 'Connection to your server refused',
  'سرور شما روی پورت مسیر اتصال را رد می‌کند؛ سرویس Xray/sing-box و پورت را بررسی کنید.': 'Your server refuses connections on the path\'s port; check the Xray/sing-box service and the port.',
  'مهلت اتصال به سرور شما تمام شد': 'Connection to your server timed out',
  'سرور شما دیر جواب می‌دهد یا فایروال آن اتصال نودهای CDN را بی‌پاسخ می‌گذارد؛ فایروال، بار سرور و مسیر شبکه‌ی آن را بررسی کنید.': 'Your server responds slowly or its firewall leaves the CDN nodes\' connections unanswered; check the firewall, server load and its network route.',
  'پاسخ نامعتبر از سرور شما': 'Invalid response from your server',
  'سرور شما اتصال را پذیرفت ولی پاسخ تونل نداد (مثلاً ۴۰۴ یا ۴۰۰)؛ مسیر، پروتکل و TLS ورودی سرور را با «بررسی کانفیگ سرور» مقایسه کنید.': 'Your server accepted the connection but gave no tunnel response (e.g. 404 or 400); compare the server inbound\'s path, protocol and TLS with “Server config check”.',
  'سقف تعداد اتصال پر شد': 'Connection limit reached',
  'به سقف اتصال همزمان رسیده‌اید؛ «حداکثر اتصال هر IP» را بیشتر کنید یا پلن با اتصال بیشتر بگیرید.': 'You have reached the concurrent-connection cap; raise “Max connections per IP” or get a plan with more connections.',
  'کاربر خارج از کشورهای مجاز': 'User outside the allowed countries',
  'کاربرانی از کشوری خارج از «کشورهای مجاز» وصل شده‌اند؛ اگر لازم است فهرست کشورها را تغییر دهید.': 'Users from a country outside “Allowed countries” connected; change the country list if needed.',
  'کلاینت با پروتکل اشتباه وصل شد': 'Client connected with the wrong protocol',
  'کلاینت با پروتکلی غیر از پروتکل مسیر وصل می‌شود؛ لینک اشتراک را دوباره از «پیکربندی آماده» بگیرید.': 'The client connects with a protocol other than the path\'s; get the share link again from “Ready config”.',
