  'در حال اندازه‌گیری سرعت آپلود…': 'Measuring upload speed…',
  'تست کامل شد.': 'Test complete.',
  'مرورگر اجازه‌ی اندازه‌گیری کامل را نداد.': 'The browser did not allow a full measurement.',
  'دامنه در دسترس است': 'The domain is reachable',
  '(یک رفت‌وبرگشت حدود': '(one round trip about',
  'میلی‌ثانیه)': 'ms)',
  'ولی سرور CDN هنوز اجازه‌ی تست سرعت از صفحه‌ی ناحیه کاربری را نمی‌دهد. چند دقیقه بعد دوباره امتحان کنید؛ اگر ادامه داشت به پشتیبانی اطلاع دهید.': 'but the CDN server doesn\'t allow speed tests from the client area yet. Try again in a few minutes; if it persists, let support know.',
  'تعداد تست‌ها در یک دقیقه زیاد شد؛ یک دقیقه صبر کنید و دوباره امتحان کنید.': 'Too many tests within a minute; wait a minute and try again.',
  'پاسخی از دامنه‌ی شما در زمان مناسب نرسید. اینترنت خود را بررسی کنید و چند دقیقه بعد دوباره امتحان کنید.': 'No answer from your domain in time. Check your internet and try again in a few minutes.',
  'اتصال به دامنه‌ی شما برقرار نشد. اینترنت خود را بررسی کنید؛ اگر سایت در مرورگر هم باز نمی‌شود، وضعیت سرویس را در «نمای کلی» ببینید.': 'Could not connect to your domain. Check your internet; if the site doesn\'t open in the browser either, check the service status on the “Overview”.',
  'سرور CDN به تست پاسخ نداد (HTTP': 'The CDN server did not answer the test (HTTP',
  '). کمی بعد دوباره امتحان کنید.': '). Try again shortly.',
  'نتیجه به زبان ساده': 'The result in plain words',
  'این تست سرعت مسیر «شما ← CDN» است. سرعت تونل علاوه بر این به مسیر نود تا سرور شما و پهنای باند آن سرور هم بستگی دارد؛ برای آن «کیفیت تونل» را ببینید.': 'This test measures the “you → CDN” route. Tunnel speed also depends on the route from the node to your server and that server\'s bandwidth; see “Tunnel quality” for that.',
  'شناسه‌ی نود پاسخ‌دهنده (برای پشتیبانی):': 'ID of the answering node (for support):',
  'تست سرعت پس از فعال شدن سایت روی CDN (تأیید نیم‌سرورها) در دسترس است.': 'The speed test becomes available once the site is active on the CDN (nameservers verified).',
  'گواهی SSL سایت هنوز فعال نیست و این صفحه روی HTTPS است؛ مرورگر اجازه‌ی تست روی HTTP را نمی‌دهد. پس از صدور گواهی دوباره امتحان کنید.': 'The site\'s SSL certificate isn\'t active yet and this page is on HTTPS; the browser won\'t allow a test over HTTP. Try again once the certificate is issued.',
  'مقصد تست:': 'Test target:',
  '— حدود': '— about',
  'مگابایت ترافیک مصرف می‌شود که مثل ترافیک عادی سایت حساب می‌شود.': 'MB of traffic is used, counted like regular site traffic.',
  'چطور نتیجه را بخوانم؟': 'How do I read the result?',
  'تأخیر (پینگ): زمان رفت و برگشت یک درخواست کوچک. هر چه کمتر بهتر؛ زیر ۱۰۰ میلی‌ثانیه خوب است.': 'Latency (ping): the round-trip time of a small request. The lower the better; under 100 ms is good.',
  'دانلود و آپلود: سرعت دریافت و ارسال داده بین شما و CDN. معمولاً سقف آن را سرعت اینترنت خود شما تعیین می‌کند.': 'Download and upload: how fast data is received and sent between you and the CDN. Usually your own internet speed sets the ceiling.',
  'برای مقایسه‌ی منصفانه، تست را چند بار و در ساعت‌های مختلف تکرار کنید؛ Wi-Fi ضعیف و دانلودهای هم‌زمان نتیجه را پایین می‌آورند.': 'For a fair comparison, repeat the test several times at different hours; weak Wi-Fi and simultaneous downloads lower the result.',
  'کیفیت تونل': 'Tunnel quality',
  'نرخ موفقیت، قطع‌های غیرعادی و زمان اتصال هر مسیر تونل، همراه با مشکل اصلی و راه‌حل پیشنهادی.': 'Success rate, abnormal drops and connect time for each tunnel path, with the main issue and a suggested fix.',
  'برای هر مسیر تونل نشان می‌دهد چند درصد اتصال‌ها به سرور شما رسیده‌اند، چند نشست ناگهان قطع شده‌اند و نودها با چه سرعتی به سرور شما وصل می‌شوند.': 'For each tunnel path it shows what percentage of connections reached your server, how many sessions dropped suddenly and how fast the nodes connect to your server.',
  'وقتی کاربران از قطعی یا کندی شکایت می‌کنند، یا بعد از تغییر کانفیگ سرور.': 'When users complain about outages or slowness, or after changing the server config.',
  'نرخ موفقیت بالای ۹۸٪ و قطع غیرعادی زیر ۲٪ یعنی مسیر سالم است.': 'A success rate above 98% and abnormal drops below 2% mean the path is healthy.',
  'تغییر پورت یا مسیر روی سرور بدون به‌روزرسانی مسیر در صفحه تونل.': 'Changing the port or path on the server without updating the path on the tunnel page.',
  'مصرف تونل': 'Tunnel usage',
  'مصرف روزانه‌ی تونل به تفکیک پروتکل و مسیر، مصرف این ماه و پیش‌بینی تاریخ اتمام ترافیک.': 'Daily tunnel usage by protocol and path, this month\'s usage and a forecast of when traffic runs out.',
  'کانفیگ Xray یا sing-box سرور خود را بچسبانید تا با مسیرهای تونل این سایت مقایسه و اشکال‌های رایج پیدا شود — فقط در مرورگر شما.': 'Paste your server\'s Xray or sing-box config to compare it with this site\'s tunnel paths and find common mistakes — only in your browser.',
  'تست سرعت': 'Speed test',
  'تأخیر، سرعت دانلود و آپلود از دستگاه شما تا دامنه‌ی شما روی CDN، با توضیح ساده‌ی نتیجه.': 'Latency, download and upload speed from your device to your domain on the CDN, with a plain explanation of the result.',
