  'خط وارد نشد:': 'line(s) not imported:',
  'در سرویس DNS قبلی گزینه Export یا «دریافت فایل زون» را بزنید و محتوای آن را اینجا قرار دهید. رکوردهای SOA و NS ریشه نادیده گرفته می‌شوند. بعد از ورود، پروکسی رکوردهای وب را بررسی کنید.': 'In your previous DNS service use Export or “download zone file” and paste its content here. SOA and root NS records are ignored. After importing, check the proxy on the web records.',
