  'فعال‌سازی DNSSEC': 'Enable DNSSEC',
  'بله، غیرفعال شود': 'Yes, disable it',
  'پیش از غیرفعال کردن، رکورد DS را از پنل ثبت‌کننده دامنه (مثلاً ایرنیک) حذف کنید و حداقل ۲۴ ساعت صبر کنید.': 'Before disabling, remove the DS record at the domain registrar (e.g. IRNIC) and wait at least 24 hours.',
  'اگر DS در ثبت‌کننده باقی بماند و DNSSEC اینجا خاموش شود، دامنه برای بسیاری از کاربران از دسترس خارج می‌شود.': 'If the DS stays at the registrar while DNSSEC is turned off here, the domain becomes unreachable for many users.',
  'DNSSEC فعال شد؛ حالا رکورد DS را در ثبت‌کننده دامنه وارد کنید.': 'DNSSEC enabled; now enter the DS record at your domain registrar.',
  'DNSSEC غیرفعال شد.': 'DNSSEC disabled.',
  'DNSSEC پاسخ‌های DNS دامنه را امضا می‌کند تا کسی نتواند آن‌ها را در مسیر جعل کند. فعال‌سازی دو مرحله دارد: اینجا روشنش می‌کنید، سپس رکورد DS را در ثبت‌کننده دامنه ثبت می‌کنید.': 'DNSSEC signs the domain\'s DNS answers so nobody can forge them on the way. Enabling has two steps: you turn it on here, then register the DS record at the domain registrar.',
  'DNSSEC روشن است. اگر هنوز رکورد DS را در ثبت‌کننده ثبت نکرده‌اید، از مقادیر زیر استفاده کنید.': 'DNSSEC is on. If you haven\'t registered the DS record at the registrar yet, use the values below.',
