  'کپی DNSKEY': 'Copy DNSKEY',
  'ثبت DS در ثبت‌کننده دامنه': 'Registering the DS at the domain registrar',
  'دامنه‌های ‎.ir (ایرنیک)': '‎.ir domains (IRNIC)',
  'وارد nic.ir شوید و با شناسه ایرنیک خود وارد حساب شوید.': 'Go to nic.ir and sign in with your IRNIC handle.',
  'از «مدیریت دامنه» دامنه را انتخاب کنید و بخش DNSSEC / رکورد DS را باز کنید.': 'Under “Domain management” select the domain and open the DNSSEC / DS record section.',
  'مقادیر Key Tag، Algorithm، Digest Type و Digest بالا را وارد و ثبت کنید.': 'Enter the Key Tag, Algorithm, Digest Type and Digest values above and submit.',
  'اگر این گزینه را در پنل نمی‌بینید، از طریق پشتیبانی ایرنیک درخواست ثبت DS بدهید.': 'If you don\'t see this option in the panel, ask IRNIC support to register the DS.',
  'سایر ثبت‌کننده‌ها': 'Other registrars',
  'در پنل دامنه به دنبال DNSSEC یا DS Records بگردید و همان چهار مقدار را وارد کنید. ثبت DS معمولاً تا ۲۴ ساعت طول می‌کشد.': 'Look for DNSSEC or DS Records in the domain panel and enter the same four values. Registering the DS usually takes up to 24 hours.',
