  'وضعیت سرویس، مراحل راه‌اندازی، مصرف و اقدامات سریع در یک نگاه.': 'Service status, setup steps, usage and quick actions at a glance.',
  'راهنما و آموزش': 'Help and tutorials',
  'آموزش‌های قدم‌به‌قدم برای راه‌اندازی، امنیت، کش و رفع خطاهای رایج — بدون نیاز به دانش فنی زیاد.': 'Step-by-step tutorials for setup, security, caching and fixing common errors — no deep technical knowledge needed.',
  'رکوردهای DNS مشخص می‌کنند هر نام (سایت، ایمیل، زیردامنه) به کدام سرور برود. رکوردهای وب را پروکسی کنید تا از CDN عبور کنند.': 'DNS records decide which server each name (site, email, subdomain) goes to. Proxy the web records so they go through the CDN.',
  'هر رکورد یک نام (مثل www) را به یک مقصد (آی‌پی یا نام دیگر) وصل می‌کند. رکورد «پروکسی‌شده» ترافیک را از CDN عبور می‌دهد.': 'Each record points a name (like www) to a destination (an IP or another name). A “proxied” record sends traffic through the CDN.',
  'پیش از تغییر نیم‌سرورها همه رکوردهای فعلی را وارد کنید؛ بعد از آن هر زمان سرور یا سرویس جدیدی اضافه کردید.': 'Enter all current records before changing nameservers; after that, whenever you add a new server or service.',
  'A یا CNAME مربوط به @ و www: پروکسی روشن. MX، mail، ftp و رکوردهای TXT: فقط DNS. TTL: ۵ دقیقه.': 'A or CNAME for @ and www: proxy on. MX, mail, ftp and TXT records: DNS only. TTL: 5 minutes.',
  'پروکسی کردن رکورد mail یا ftp (ایمیل و FTP قطع می‌شود).': 'Proxying the mail or ftp record (email and FTP stop working).',
  'فراموش کردن رکوردهای MX و SPF هنگام انتقال.': 'Forgetting the MX and SPF records when migrating.',
  'تغییر نیم‌سرورها پیش از وارد کردن کامل رکوردها.': 'Changing nameservers before all records are entered.',
  'سقف تعداد رکوردهای پلن پر شده است': 'The plan\'s record limit is reached',
  'امضای دیجیتال پاسخ‌های DNS برای جلوگیری از جعل؛ پس از فعال‌سازی باید رکورد DS را در ثبت‌کننده دامنه وارد کنید.': 'Digital signatures on DNS answers to prevent forgery; after enabling, you must enter the DS record at the domain registrar.',
  'DNSSEC با امضای دیجیتال تضمین می‌کند پاسخ DNS دامنه شما در مسیر تغییر داده نشده است.': 'DNSSEC uses digital signatures to guarantee your domain\'s DNS answers weren\'t altered on the way.',
  'بعد از اینکه نیم‌سرورها تأیید شدند و سایت پایدار کار می‌کند.': 'Once the nameservers are verified and the site runs stably.',
  'برای اغلب سایت‌ها اختیاری است؛ اگر فعال می‌کنید، DS را دقیق و کامل در ثبت‌کننده وارد کنید.': 'Optional for most sites; if you enable it, enter the DS at the registrar accurately and completely.',
  'خاموش کردن DNSSEC در اینجا بدون حذف DS از ثبت‌کننده (دامنه از دسترس خارج می‌شود).': 'Turning DNSSEC off here without removing the DS at the registrar (the domain becomes unreachable).',
  'تغییر نیم‌سرورها به سرویس دیگر در حالی که DS قدیمی هنوز ثبت است.': 'Moving the nameservers to another service while the old DS is still registered.',
  'با ارتقای پلن، پاسخ‌های DNS دامنه شما امضای دیجیتال می‌گیرند.': 'Upgrade your plan to digitally sign your domain\'s DNS answers.',
  'با ارتقای پلن، نیم‌سرورهای ما می‌توانند DNS ثانویهٔ دامنه شما باشند و زون را از سرور DNS خودتان انتقال دهند.': 'Upgrade your plan so our nameservers can be the secondary DNS of your domain and transfer the zone from your own DNS server.',
  'پنل نمایندگی': 'Reseller panel',
  'سایت‌های CDN مشتریان نهایی شما: ساخت سایت، گزارش مصرف و هزینه عمده، و مدیریت کامل هر سایت.': 'Your end customers\' CDN sites: create sites, usage and wholesale cost reports, and full management of each site.',
  'بخش نمایندگی بارگذاری نشد.': 'The reseller section failed to load.',
