  'نام باکت باید ۳ تا ۴۰ کاراکتر از حروف کوچک انگلیسی، رقم و - باشد و با حرف یا رقم شروع و تمام شود.': 'The bucket name must be 3 to 40 characters of lowercase English letters, digits and -, and start and end with a letter or digit.',
