  'همین حالا آن را کپی کنید و در جای امنی (مثلاً مدیر گذرواژه یا تنظیمات برنامهٔ خودتان) نگه دارید؛ ما آن را دوباره نشان نمی‌دهیم و اگر گم شود باید کلید جدید بسازید.': 'Copy it now and keep it somewhere safe (a password manager or your app\'s settings); we won\'t show it again, and if it is lost you have to create a new key.',
  'کلید قبلی همین حالا باطل شد؛ برنامه‌ها و اسکریپت‌هایی که از آن استفاده می‌کنند را با کلید جدید به‌روز کنید.': 'The previous key was revoked just now; update the apps and scripts that use it with the new key.',
