  'برنامه‌ها، اسکریپت‌ها و پشتیبان‌گیری‌هایی که از کلید فعلی استفاده می‌کنند تا وقتی کلید جدید را در آن‌ها وارد نکنید کار نمی‌کنند. فایل‌ها و نشانی‌های CDN تغییری نمی‌کنند.': 'Apps, scripts and backups that use the current key stop working until you enter the new key in them. Files and CDN URLs don\'t change.',
