  'حالت یادگیری': 'Learning mode',
  'WAF چند روز ترافیک واقعی سایت را فقط مشاهده می‌کند و برای کاهش مسدودسازی‌های اشتباه و تنظیم محدودیت نرخ پیشنهاد می‌دهد.': 'For a few days the WAF only observes your site\'s real traffic, then proposes changes that cut false positives and set sensible rate limits.',
  'ابتدا تغییرات ذخیره‌نشدهٔ این صفحه را ذخیره یا لغو کنید.': 'Save or discard the unsaved changes on this page first.',
  'وضعیت حالت یادگیری دریافت نشد': 'Could not load the learning mode status',
  'شروع حالت یادگیری انجام نشد': 'Could not start learning mode',
  'توقف حالت یادگیری انجام نشد': 'Could not stop learning mode',
  'حالت یادگیری شروع شد؛ در این مدت WAF چیزی را مسدود نمی‌کند.': 'Learning mode started; the WAF blocks nothing while it runs.',
  'حالت یادگیری متوقف شد و WAF به حالت کار عادی خود برگشت.': 'Learning mode stopped; the WAF is back to its normal mode.',
  'مدت یادگیری باید عددی بین ۱ تا ۳۰ روز باشد.': 'The learning period must be a whole number of days from 1 to 30.',
  'شروع حالت یادگیری': 'Start learning mode',
  'شروع یادگیری': 'Start learning',
  'به مدت {0} روز WAF این سایت فقط ثبت می‌کند و هیچ درخواستی را به خاطر قوانین WAF مسدود نمی‌کند (مثل حالت «فقط ثبت»). فایروال، محدودیت نرخ و حفاظت DDoS مثل قبل کار می‌کنند.': 'For {0} day(s) this site\'s WAF only logs and blocks no request because of WAF rules (like “Log only” mode). The firewall, rate limits and DDoS protection keep working as before.',
  'در پایان، پیشنهادها اینجا نمایش داده می‌شوند و تا شما تأیید نکنید هیچ‌کدام اعمال نمی‌شود.': 'When it ends, the proposals appear here, and none is applied until you approve it.',
  'توقف حالت یادگیری': 'Stop learning mode',
  'توقف یادگیری': 'Stop learning',
  'ادامهٔ یادگیری': 'Keep learning',
  'WAF بی‌درنگ به حالت کار عادی خود برمی‌گردد. پیشنهادهایی که تا الان ساخته شده‌اند باقی می‌مانند؛ هرچه یادگیری کوتاه‌تر باشد پیشنهادها کمتر و نامطمئن‌ترند.': 'The WAF returns to its normal mode right away. Proposals made so far are kept; the shorter the learning, the fewer and less certain the proposals.',
  'در هر بار حداکثر ۱۰۰ پیشنهاد را می‌توانید اعمال کنید.': 'You can apply at most 100 proposals at a time.',
  'اعمال پیشنهادهای انتخاب‌شده': 'Apply the selected proposals',
  'اعمال {0} پیشنهاد': 'Apply {0} proposal(s)',
  'این تغییرها در تنظیمات سایت ذخیره می‌شوند و تا چند ثانیه روی همه سرورها اعمال می‌شوند:': 'These changes are saved to the site\'s settings and reach every server within seconds:',
  'هر تغییر را بعداً می‌توانید از همین صفحه (استثناها و بسته‌ها) یا صفحهٔ «محدودیت نرخ» ویرایش یا حذف کنید.': 'You can edit or remove each change later on this page (exclusions and packs) or on the “Rate limiting” page.',
  'اعمال پیشنهادها انجام نشد': 'Could not apply the proposals',
  '{0} پیشنهاد اعمال شد و تا چند ثانیه روی همه سرورها فعال می‌شود.': '{0} proposal(s) applied; they take effect on every server within seconds.',
  'فقط مشاهده می‌کند: در مدت یادگیری WAF مثل حالت «فقط ثبت» کار می‌کند و هیچ درخواستی را به خاطر قوانین WAF مسدود نمی‌کند.': 'Observe only: while learning, the WAF works like “Log only” mode and blocks no request because of WAF rules.',
  'فایروال، محدودیت نرخ و حفاظت DDoS در این مدت مثل قبل کار می‌کنند.': 'The firewall, rate limits and DDoS protection keep working as before.',
  'در پایان، پیشنهادهایی برای استثنای WAF، محدودیت نرخ و خاموش کردن بسته‌های بی‌فایده می‌بینید که هیچ‌کدام خودکار اعمال نمی‌شود.': 'At the end you get proposals for WAF exclusions, rate limits and turning off useless packs; none of them is applied automatically.',
  'مدت یادگیری': 'Learning period',
  'بین ۱ تا ۳۰ روز؛ ۷ روز پیشنهادی است تا ترافیک همهٔ روزهای هفته دیده شود.': '1 to 30 days; 7 is recommended so every day of the week is seen.',
  'شروع دوبارهٔ یادگیری': 'Start learning again',
  'در حال یادگیری': 'Learning',
  '{0} مانده': '{0} left',
