  'زمان شروع': 'Started',
  'زمان پایان': 'Ends',
  'درخواست‌های بررسی‌شده': 'Requests observed',
  'پیش‌نمایش تغییر': 'Preview change',
  'بستن پیش‌نمایش': 'Close preview',
  'اعمال شده': 'Applied',
  'اطمینان: {0}': 'Confidence: {0}',
  'موردی انتخاب نشده': 'Nothing selected',
  'هنوز پیشنهادی نیست': 'No proposals yet',
  'پیشنهادی برای تغییر نیست': 'No changes to propose',
  'پیشنهادها با دیده شدن ترافیک کافی ساخته می‌شوند و در پایان یادگیری کامل می‌شوند.': 'Proposals are made once enough traffic has been seen and are completed when learning ends.',
  'در مدت یادگیری مسدودسازی اشتباه یا مسیر پرترافیکی که به محدودیت نرخ نیاز داشته باشد دیده نشد؛ تنظیمات فعلی مناسب به نظر می‌رسد.': 'No false positives and no busy path needing a rate limit were seen while learning; the current settings look right.',
  'اعمال موارد انتخاب‌شده': 'Apply selected',
  'پیشنهادهای حالت یادگیری': 'Learning mode proposals',
  'پیشنهادها ({0})': 'Proposals ({0})',
  'یادگیری هنوز ادامه دارد؛ این پیشنهادها اولیه‌اند و با ترافیک بیشتر دقیق‌تر می‌شوند.': 'Learning is still running; these proposals are preliminary and get more accurate with more traffic.',
  'در مدت یادگیری WAF درخواست‌های مخرب را هم مسدود نمی‌کند؛ اگر سایت زیر حمله است اول حمله را مهار کنید.': 'While learning, the WAF does not block malicious requests either; if the site is under attack, deal with the attack first.',
  'در این مدت WAF فقط ثبت می‌کند و چیزی را مسدود نمی‌کند؛ پایان یادگیری خودکار است و پس از آن WAF به حالت کار انتخاب‌شده برمی‌گردد.': 'Meanwhile the WAF only logs and blocks nothing; learning ends by itself and the WAF then returns to the mode you chose.',
  'یادگیری کامل شد.': 'Learning finished.',
  '{0} درخواست از {1} تا {2} بررسی شد.': '{0} requests were observed from {1} to {2}.',
  'یادگیری دوباره': 'Learn again',
