  'وقتی تعداد بازدیدکنندگان هم‌زمان از ظرفیت بیشتر شود، بقیه در یک صف منصفانه منتظر می‌مانند تا سایت از دسترس خارج نشود.': 'When more visitors arrive than the site can take, the rest wait in a fair queue so the site stays up.',
