  'کد یک‌بارمصرف ایمیلی': 'E-mail one-time code',
  'کاربر ایمیلش را وارد می‌کند و کدی ۶ رقمی دریافت می‌کند؛ فقط ایمیل‌ها یا دامنه‌های فهرست.': 'The user enters their e-mail and receives a 6-digit code; only listed e-mails or domains.',
