  'با کلید جدید همهٔ کاربرانی که الان وارد شده‌اند خارج می‌شوند و کدهای ارسال‌شده باطل می‌شوند. اگر احتمال می‌دهید کوکی یا کدی لو رفته این کار را انجام دهید.': 'A new key signs out everyone who is signed in and voids codes already sent. Do this if a cookie or code may have leaked.',
