  'بازهٔ زمانی': 'Period',
  'در اوج ترافیک (حراج، ثبت‌نام، اعلام نتایج) بازدیدکنندگان اضافه را در صف نگه دارید تا سایت برای همه کار کند.': 'At traffic peaks (sales, sign-ups, results day) hold extra visitors in a queue so the site keeps working for everyone.',
  'هر نود تعداد بازدیدکنندگان فعال را می‌شمارد؛ تا سقف، همه وارد می‌شوند و بقیه صفحهٔ صف را با جایگاه تقریبی می‌بینند و به ترتیب وارد می‌شوند.': 'Each node counts active visitors; up to the limit everyone gets in, the rest see a queue page with their approximate position and get in in order.',
  'وقتی انتظار هجوم ناگهانی بازدیدکننده دارید و سرور شما ظرفیت محدودی دارد.': 'When you expect a sudden rush of visitors and your server has limited capacity.',
  'سقف را کمی کمتر از ظرفیت واقعی سرور بگذارید و فقط مسیرهای سنگین (مثل /checkout) را پوشش دهید.': 'Set the limit slightly below your server\'s real capacity and cover only heavy paths (like /checkout).',
  'سقف خیلی پایین (صف در ترافیک عادی هم تشکیل می‌شود).': 'A limit that is too low (a queue forms even at normal traffic).',
  'پوشش دادن مسیرهای API یا وب‌هوک (برنامه‌ها صفحهٔ صف را نمی‌فهمند؛ آن‌ها را در استثناها بگذارید).': 'Covering API or webhook paths (programs do not understand the queue page; list them as exceptions).',
  'با ارتقای پلن، در اوج ترافیک بازدیدکنندگان در صف منصفانه منتظر می‌مانند و سایت از دسترس خارج نمی‌شود.': 'Upgrade your plan so visitors wait in a fair queue at traffic peaks and the site stays up.',
  'پنل مدیریت، نسخهٔ آزمایشی یا هر مسیر دیگر را فقط برای ایمیل‌ها یا آی‌پی‌های مشخص باز کنید.': 'Open the admin panel, a staging copy or any other path only to specific e-mails or IPs.',
  'CDN پیش از رسیدن درخواست به سرور شما ورود را بررسی می‌کند: کد یک‌بارمصرف ایمیلی، فهرست آی‌پی یا هر دو.': 'The CDN checks sign-in before a request reaches your server: e-mail one-time code, IP list or both.',
  'برای پنل مدیریت (wp-admin و …)، محیط تست و ابزارهای داخلی که نباید عمومی باشند.': 'For admin panels (wp-admin, …), staging and internal tools that must not be public.',
  'برای تیم‌ها از @دامنهٔ شرکت استفاده کنید و اعتبار ورود را کوتاه (مثلاً ۸ ساعت) بگذارید.': 'For teams use your company @domain and keep sign-ins short (for example 8 hours).',
  'هم‌پوشانی مسیر دو برنامه (ذخیره نمی‌شود).': 'Overlapping paths of two apps (cannot be saved).',
  'محافظت از مسیری که برنامه‌های موبایل یا API از آن استفاده می‌کنند.': 'Protecting a path that mobile apps or APIs use.',
  'با ارتقای پلن، بخش‌هایی از سایت را پشت ورود ایمیلی یا فهرست آی‌پی قرار دهید.': 'Upgrade your plan to put parts of the site behind an e-mail sign-in or an IP list.',
