  ': sockopt.tcpKeepAlive* فقط اتصال TCP بین نود و سرور را زنده نگه می‌دارد، نه جریان بیکار تونل را؛ برای آن keepalive برنامه‌ی کاربر را طبق «تنظیمات پیشنهادی» بگذارید.': ': sockopt.tcpKeepAlive* only keeps the TCP connection between the node and your server alive, not an idle tunnel stream; for that, set the user app\'s keepalive as shown in “Recommended app settings”.',
  'ویندوز، لینوکس، مک': 'Windows, Linux, macOS',
  'iOS و مک': 'iOS and macOS',
  'روشن — concurrency بین ۴ تا ۸': 'On — concurrency between 4 and 8',
  'برای WebSocket / HTTPUpgrade چند اتصال کاربر روی یک اتصال می‌نشیند و اتصال‌های پشت‌سرهم کمتر می‌شود؛ بیشتر از ۸ نگذارید.': 'For WebSocket / HTTPUpgrade several user connections share one connection and back-to-back connects drop; do not go above 8.',
  'gRPC خودش چند جریان را روی یک اتصال HTTP/2 می‌برد؛ Mux روی آن فقط تأخیر اضافه می‌کند.': 'gRPC already carries many streams over one HTTP/2 connection; Mux on top only adds latency.',
  'XHTTP اتصال‌ها را با XMUX مدیریت می‌کند؛ Mux را خاموش بگذارید.': 'XHTTP manages its connections with XMUX; keep Mux off.',
  'در لینک اشتراک هست (mode=gun).': 'Already in the share link (mode=gun).',
  'ثانیه؛ هر چند ثانیه بی‌کاری یک ping HTTP/2 می‌فرستد تا اتصال بیکار بسته نشود.': 'Seconds; after this much idle time an HTTP/2 ping is sent so the idle connection is not closed.',
  'ثانیه؛ اگر پاسخ ping تا این مدت نیامد اتصال دوباره ساخته می‌شود.': 'Seconds; if the ping is not answered within this time the connection is rebuilt.',
  'بدون جریان فعال ping نمی‌فرستد (مصرف کمتر باتری).': 'No pings without an active stream (less battery use).',
  'در لینک اشتراک پنل (پارامتر extra) هست؛ در v2rayNG و v2rayN در فیلد «xhttp extra» هم می‌توانید بچسبانید.': 'Already in the panel\'s share link (extra parameter); in v2rayNG and v2rayN you can also paste it into the “xhttp extra” field.',
  'حالت خودکار؛ اگر شبکه‌ی کاربر ناپایدار است packet-up را امتحان کنید.': 'Automatic mode; if the user\'s network is unstable, try packet-up.',
  'نسخه‌ی HTTP/3 همین مسیر (QUIC)؛ اگر شبکه‌ی کاربر UDP را محدود می‌کند همان h2 را نگه دارید.': 'The HTTP/3 (QUIC) variant of this path; if the user\'s network restricts UDP, keep h2.',
  'ثانیه (Xray نسخه‌ی ۲۵ به بعد)؛ در رابط برنامه نیست، در کانفیگ سفارشی JSON بگذارید. در نسخه‌های قدیمی‌تر نادیده گرفته می‌شود.': 'Seconds (Xray 25 and later); not in the app\'s UI, set it in a custom JSON config. Older versions ignore it.',
  'HTTPUpgrade تنظیم ping ندارد؛ برای اتصال‌های طولانی بیکار gRPC را ترجیح دهید.': 'HTTPUpgrade has no ping setting; for long idle connections prefer gRPC.',
  'در لینک اشتراک هست؛ مسیر h2 همیشه stream-one است.': 'Already in the share link; an h2 path is always stream-one.',
  'سرور Xray از multiplex هسته‌ی sing-box پشتیبانی نمی‌کند؛ روشن کردنش اتصال را خراب می‌کند. در Hiddify گزینه‌ی Mux را خاموش بگذارید.': 'An Xray server does not support sing-box multiplex; turning it on breaks the connection. In Hiddify keep the Mux option off.',
  'هر چند ثانیه بی‌کاری یک ping HTTP/2 می‌فرستد.': 'Sends an HTTP/2 ping after this much idle time.',
  'اگر پاسخ ping تا این مدت نیامد اتصال دوباره ساخته می‌شود.': 'If the ping is not answered within this time the connection is rebuilt.',
  'sing-box برای WebSocket ping ندارد؛ heartbeatPeriod را روی ورودی Xray سرور {0} ثانیه بگذارید.': 'sing-box has no WebSocket ping; set heartbeatPeriod to {0} seconds on the Xray server inbound.',
