  'فقط تنظیمات پایداری:': 'Stability settings only:',
  'این صفحه فاصله‌ی keepalive / ping، Mux و انتخاب پروتکل را از روی مهلت‌های واقعی مسیرهای همین سرویس پیشنهاد می‌دهد تا اتصال‌های طولانی بی‌دلیل قطع نشوند.': 'This page recommends keepalive / ping intervals, Mux and the protocol from the real timeouts of this service\'s paths, so long connections are not cut for no reason.',
