  'پس از ساخت و ذخیره‌ی اولین مسیر در صفحه‌ی تونل، تنظیمات پیشنهادی هر برنامه اینجا نمایش داده می‌شود.': 'Once you create and save the first path on the tunnel page, the recommended settings of each app are shown here.',
