  'همه‌ی نودهای این سرویس HTTP/3 دارند؛ در «پیکربندی آماده» نسخه‌ی HTTP/3 این مسیر (alpn=h3) را هم می‌گیرید.': 'Every node of this service speaks HTTP/3; “Ready config” also gives you the HTTP/3 variant of this path (alpn=h3).',
  'همه‌ی نودهای این سرویس هنوز HTTP/3 ندارند؛ از همان نسخه‌ی h2 استفاده کنید.': 'Not every node of this service has HTTP/3 yet; use the h2 variant.',
