  'این مقدارها را در outbound همین مسیر بگذارید؛ «پیکربندی آماده» خروجی sing-box را با همین مقدارها می‌سازد.': 'Put these values in this path\'s outbound; “Ready config” builds the sing-box outbound with them.',
