  'یک اسکریپت کوچک از همان دامنهٔ سایت زمان بارگذاری صفحه را در مرورگر بازدیدکنندگان می‌سنجد.': 'A small script served from the site\'s own domain measures page loading in visitors\' browsers.',
  'پایش کاربران واقعی روشن باشد': 'Real user monitoring on',
  'بدون کوکی، بدون ذخیرهٔ آی‌پی و بدون هیچ شناسه‌ای؛ فقط زمان‌ها، نوع دستگاه و مسیر صفحه (بدون پارامترها).': 'No cookies, no stored IPs and no identifiers; only timings, device type and the page path (without parameters).',
  'درصد بازدیدهای نمونه‌برداری‌شده': 'Share of page views sampled',
  '۱ تا ۱۰۰٪ (پیش‌فرض ۱۰٪). برای سایت‌های پربازدید درصد کمتر کافی است.': '1 to 100% (default 10%). Busy sites need less.',
  'افزودن اسکریپت': 'Adding the script',
  'CDN تگ اسکریپت را به صفحه‌های HTML اضافه می‌کند. برای این کار صفحه‌ها بدون فشرده‌سازی از سرور شما گرفته می‌شوند (کمی پهنای باند بیشتر بین CDN و سرور شما). سایت‌هایی با CSP سخت‌گیرانه (nonce) باید حالت دستی را انتخاب کنند.': 'The CDN adds the script tag to HTML pages. For that, pages are fetched from your server uncompressed (a little more bandwidth between the CDN and your server). Sites with a strict CSP (nonces) must use manual mode.',
  'دستی': 'Manual',
